	'upd_req_writable_help' => "PHP se ejecuta como «%1\$s» y solo puede leer estas carpetas: pertenecen al usuario que las subió (p. ej. por SFTP), con los permisos habituales 755 (otros: solo lectura).\nSolución por SSH (carpeta: %2\$s):\n• sudo chown -R %1\$s %2\$s – los archivos pertenecen a PHP (por SFTP entonces solo legibles)\n• o compartido: sudo chown -R tuusuario:%1\$s %2\$s y chmod 2775 en las carpetas, 664 en los archivos\nSin SSH, en el cliente SFTP (p. ej. FileZilla: clic derecho → Permisos de archivo): poner las carpetas a 777 (leer, escribir, ejecutar para todos – «ejecutar» en una carpeta significa «puede entrar»), recursivo, solo carpetas. Instalar la actualización y volver a 755.\nO actualizar a mano: subir los archivos de nunext.zip sobre los antiguos.",
