	'smp_intro' => 'Instala una pequeña aplicación de ejemplo: 5 usuarios con 5 niveles de acceso, formularios para clientes, productos y pedidos, y un formulario con todos los tipos de objeto y formatos. Cada registro, tabla e ID empieza por sample_, así que se puede quitar por completo. Los formularios se escriben en el formato de nuBuilder Forte y también se abren en nuBuilder Forte. También incluye cuatro paneles: en la página de inicio de los usuarios de ejemplo, en el formulario de clientes (pestaña Statistics) y en el formulario de inicio de ejemplo.',
	'smp_intro_home' => 'Páginas de inicio de los usuarios: sample_sales (Dario) recibe un puesto de ventas con favoritos y un grupo solo para el permiso sample_discount, sample_manager (Carla) una página con dos pestañas y un grupo solo para el equipo Lead, sample_editor (Ben) una lista de captura con un informe solo para algunos puestos. sample_viewer y sample_secure conservan la página automática con sus formularios e informes.',
