	'rd_help' => 'Ayuda',
	'rd_help_text' => 'Arrastre campos desde la izquierda a una sección, o haga clic en Campo / Texto / Rectángulo / Línea / Imagen. Las secciones se imprimen en este orden: encabezado del informe (una vez), encabezado de página (cada página), encabezados de grupo, detalle (cada fila), pies de grupo, pie de página, pie del informe.\\nMueva los objetos con el ratón (también a otra sección) o con las flechas (Mayús = 4 mm, Alt = 0,25 mm); los tiradores cambian el tamaño. Mayús-clic o un marco para seleccionar varios, luego los botones de alinear.\\nCtrl+Z / Ctrl+Y deshacer y rehacer, Ctrl+C / Ctrl+V copiar, Ctrl+D duplica, Supr elimina, Ctrl+S guarda.\\nCampos: una columna, SUM(columna) o AVERAGE(a, b) – sumas por grupo de orden. Los textos pueden contener #page#, #pages#, #code#, #description#, #nu_date# y cualquier variable hash (p. ej. campos del formulario de inicio).\\nUn valor que empieza por #B#rrggbb| o #F#rrggbb| recibe ese color de fondo / texto (formato condicional desde la fuente de datos).\\nLa vista previa imprime el diseño actual con criterios vacíos; el diseño se guarda en el formato de nuBuilder Forte.',
