	'secchk_settings' => 'Ajustes de seguridad',
	'secchk_set_rights_globeadmin_only' => 'Solo el globeadmin concede derechos de administración',
	'secchk_set_rights_globeadmin_only_tip' => 'Los derechos de guardar, añadir, nuevo, eliminar y clonar en el generador de formularios, procedimientos, generador SQL, configuración, usuarios y niveles de acceso dan control total (código en el servidor, derechos propios). Activado: solo el globeadmin los concede o asigna niveles de acceso que los tienen; nadie más cambia a esos usuarios; nadie cambia su propio nivel de acceso ni sus derechos; los demás no pueden guardar estos formularios del sistema mediante los formularios.',
	'secchk_set_protect_fields' => 'No guardar desde el navegador los campos de solo lectura y ocultos',
	'secchk_set_protect_fields_tip' => 'Los campos con acceso «solo lectura» u «oculto» conservan su valor guardado, envíe lo que envíe el navegador. Desactivado = como nuBuilder Forte: el JavaScript que rellena esos campos (p. ej. nuSetValue en un campo oculto) sigue funcionando.',
	'secchk_set_record_check' => 'Registros solo a través de la lista del formulario',
	'secchk_set_record_check_tip' => 'Un registro solo se puede abrir, guardar o eliminar si el SQL de lista del formulario (con las variables hash del usuario) lo encuentra. No se comprueban los formularios sin SQL de lista ni el SQL que necesita código Before Browse. Desactivado = como nuBuilder Forte.',
	'secchk_set_field_access_ga' => 'Aplicar las reglas de acceso a datos al globeadmin',
	'secchk_set_field_access_ga_tip' => 'Para pruebas: las reglas de acceso a campos y columnas también se aplican al globeadmin. Desactivado = el globeadmin ve todo con el acceso de nuBuilder Forte.',
	'secchk_set_md5_login' => 'Aceptar contraseñas md5 antiguas',
	'secchk_set_md5_login_tip' => 'Las contraseñas de nuBuilder Forte anteriores a 4.5 son hashes md5; al iniciar sesión pasan a bcrypt. Desactivado: esos usuarios deben definir una contraseña nueva («Olvidé la contraseña» o el administrador).',
	'secchk_set_log_keep_days' => 'Conservar el registro (días)',
	'secchk_set_log_keep_days_tip' => 'Las entradas más antiguas del registro de nuBuilder Next las borra el mantenimiento (cron.php, o de vez en cuando una visita a una página). 0 = conservar todo.',
	'secchk_set_reauth_minutes' => 'Volver a pedir la contraseña después de (minutos)',
	'secchk_set_reauth_minutes_tip' => 'La actualización, las copias de seguridad, nuconfig.php, los ajustes, el clonador de aplicaciones, los clientes API, phpMyAdmin / el gestor de archivos, «Actuar como usuario» con acceso completo y estos ajustes piden la contraseña si el inicio de sesión o la última confirmación es más antiguo. 0 = no preguntar nunca.',
	'secchk_set_reauth_minutes_dev' => 'Volver a pedir la contraseña en modo desarrollador tras (minutos)',
	'secchk_set_reauth_minutes_dev_tip' => 'Solo para el globeadmin con $nuConfigDevMode = true: el desarrollo se hace sin datos reales, por eso la confirmación de la contraseña dura más (por defecto 480 = 8 horas). 0 = no preguntar nunca. Sin modo desarrollador se aplica el ajuste de arriba.',
	'secchk_set_login_token' => 'Aceptar los tokens de inicio de sesión de un solo uso de nuBuilder Forte',
	'secchk_set_login_token_tip' => 'Los enlaces index.php?u=<nombre de usuario o id>&p=<token> inician la sesión de un usuario una vez si el token coincide con LOGIN_TOKEN en sus_json («Single-User Password Token» de nuBuilder Forte; sin segundo factor, como en nuBuilder Forte). Nunca el globeadmin. Desactivado, estos enlaces abren la página de inicio de sesión.',
	'secchk_set_form_drafts_required' => 'Cambiar formularios publicados solo mediante borradores',
